import {mock,spyOn} from "bun:test";
const observations=[];
const show=v=>typeof v==="function"?{type:"function",name:v.name,length:v.length}:v===undefined?{type:"undefined"}:v;
async function observe(name,fn){try{observations.push({name,value:await fn()});}catch(e){observations.push({name,error:{name:e.name,message:e.message}});}}
await observe("namespace",()=>({mock:show(mock),spyOn:show(spyOn),keys:Object.keys(mock),own:Reflect.ownKeys(mock).map(String)}));
await observe("empty",()=>{const f=mock();return{fn:show(f),value:show(f()),keys:Reflect.ownKeys(f).map(String),state:f.mock};});
for(const x of [null,false,0,"name",{},[],undefined])await observe("input "+String(x),()=>show(mock(x)));
await observe("calls-context-results",()=>{const receiver={value:4};const f=mock(function sum(a,b){return this.value+a+b;});const value=f.call(receiver,2,3);return{fn:show(f),value,calls:f.mock.calls,contexts:f.mock.contexts,instances:f.mock.instances,results:f.mock.results,lastCall:f.mock.lastCall,name:f.getMockName(),impl:show(f.getMockImplementation())};});
await observe("nested-incomplete",()=>{let inside;const f=mock(()=>{inside=f.mock.results.map(x=>({...x}));return 7;});f();return{inside,after:f.mock.results};});
await observe("throw-identity",()=>{const reason={marker:7},f=mock(()=>{throw reason;});let same=false;try{f("x");}catch(e){same=e===reason;}return{same,calls:f.mock.calls,results:f.mock.results};});
await observe("queue-default",()=>{const f=mock(()=>"initial");f.mockImplementationOnce(()=>"one").mockReturnValueOnce("two").mockImplementation(()=>"default");return[ f(),f(),f(),f() ];});
await observe("clear-history",()=>{const f=mock(()=>9);f(1);const state=f.mock,calls=state.calls,results=state.results;const chain=f.mockClear()===f;return{chain,sameState:f.mock===state,sameCalls:f.mock.calls===calls,sameResults:f.mock.results===results,oldCalls:calls,oldResults:results,newState:f.mock,next:f()};});
await observe("reset-initial",()=>{const original=()=>7,f=mock(original);f.mockImplementationOnce(()=>2).mockReturnValue(9);f(1);const chain=f.mockReset()===f;return{chain,next:show(f()),sameImplementation:f.getMockImplementation()===original,results:f.mock.results};});
await observe("restore-plain",()=>{const original=()=>7,f=mock(original);f.mockReturnValue(9);f(1);const chain=f.mockRestore()===f;return{chain,next:show(f()),sameImplementation:f.getMockImplementation()===original,results:f.mock.results};});
await observe("async-return-reject",async()=>{const reason={failure:true},f=mock().mockResolvedValueOnce(7).mockRejectedValueOnce(reason);const p=f("ok"),q=f("bad");const samePromises=f.mock.results[0].value===p&&f.mock.results[1].value===q;const value=await p;let same=false;try{await q;}catch(e){same=e===reason;}return{samePromises,value,same,calls:f.mock.calls,types:f.mock.results.map(x=>x.type),settled:f.mock.settledResults};});
await observe("constructor-function",()=>{const f=mock(function C(x){this.x=x;});const obj=new f(7);return{value:obj.x,instance:obj instanceof f,contextsSame:f.mock.contexts[0]===obj,instancesSame:f.mock.instances[0]===obj,resultSame:f.mock.results[0].value===obj,resultType:f.mock.results[0].type};});
await observe("constructor-class",()=>{class C{constructor(x){this.x=x;}get(){return this.x;}}const f=mock(C),obj=new f(8);return{value:obj.get(),originalInstance:obj instanceof C,mockInstance:obj instanceof f,instancesSame:f.mock.instances[0]===obj,contextsSame:f.mock.contexts[0]===obj,resultSame:f.mock.results[0].value===obj};});
await observe("spy-own",()=>{const obj={n:2,method(x){return this.n+x;}},original=obj.method,desc=Object.getOwnPropertyDescriptor(obj,"method"),spy=spyOn(obj,"method"),again=spyOn(obj,"method");const value=obj.method(3);spy.mockReturnValue(10);const overridden=obj.method(8);const restore=spy.mockRestore()===spy;return{same:obj.method===original,sameRepeated:again===spy,value,overridden,restore,restoredDescriptor:JSON.stringify(Object.getOwnPropertyDescriptor(obj,"method"))===JSON.stringify(desc),history:spy.mock.calls,detached:show(spy.call(obj,6))};});
await observe("spy-inherited",()=>{const proto={f(){return this.x;}},obj=Object.create(proto);obj.x=7;const spy=spyOn(obj,"f"),ownDuring=Object.hasOwn(obj,"f"),value=obj.f();spy.mockRestore();return{ownDuring,value,ownAfter:Object.hasOwn(obj,"f"),prototypeUnchanged:obj.f===proto.f};});
await observe("spy-call-property",()=>{function original(x){return this.n+x;}const spy=spyOn(original,"call"),r=original.call({n:3},4);const calls=spy.mock.calls;spy.mockRestore();return{r,calls,ownAfter:Object.hasOwn(original,"call")};});
for(const key of ["missing","value"])await observe("spy-invalid-"+key,()=>show(spyOn({value:4},key)));
await observe("temporary-throw",()=>{const f=mock(()=>1);let caught;try{f.withImplementation(()=>2,()=>{if(f()!==2)throw new Error("wrong");throw new Error("callback");});}catch(e){caught=e.message;}return{caught,after:f()};});
await observe("temporary-async",async()=>{const f=mock(()=>1);const r=f.withImplementation(()=>2,async()=>{await Promise.resolve();return f();});const result=await r;return{result:show(result),after:f()};});
console.log(JSON.stringify({bun:Bun.version,observations},null,2));
